//! Layer-aware orthogonal router for `rataflow-view`.
//!
//! The library's step router gives every edge the same centre handles and
//! draws each one independently, so parallel edges merge into one corridor
//! and crossings become fake junctions. This module owns the geometry
//! instead: it gives every edge its own port on each node side, routes it
//! over the character grid with A*, and reports how much of the route is
//! shared with another edge.
//!
//! The route cost deliberately prefers a longer, cleaner path over a short
//! one that runs beside or through another edge — readability beats length.

use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

use rataflow::HandlePosition;

/// One side of a node box.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Side {
    Top,
    Right,
    Bottom,
    Left,
}

impl Side {
    /// Unit vector that points away from the node.
    pub fn outward(self) -> (i32, i32) {
        match self {
            Side::Top => (0, -1),
            Side::Right => (1, 0),
            Side::Bottom => (0, 1),
            Side::Left => (-1, 0),
        }
    }

    /// Direction index used by the router: 0 up, 1 right, 2 down, 3 left.
    fn dir(self) -> usize {
        match self {
            Side::Top => 0,
            Side::Right => 1,
            Side::Bottom => 2,
            Side::Left => 3,
        }
    }

    /// The library handle that sits on this side.
    pub fn handle(self) -> HandlePosition {
        match self {
            Side::Top => HandlePosition::Top,
            Side::Right => HandlePosition::Right,
            Side::Bottom => HandlePosition::Bottom,
            Side::Left => HandlePosition::Left,
        }
    }

    /// True when the side runs along x (top and bottom).
    fn horizontal(self) -> bool {
        matches!(self, Side::Top | Side::Bottom)
    }
}

/// A node box in cell coordinates. `x`/`y` are the top-left border cell.
#[derive(Debug, Clone)]
pub struct NodeBox {
    pub id: String,
    pub x: i32,
    pub y: i32,
    pub w: i32,
    pub h: i32,
    pub layer: usize,
}

impl NodeBox {
    fn contains(&self, x: i32, y: i32) -> bool {
        x >= self.x && x < self.x + self.w && y >= self.y && y < self.y + self.h
    }

    fn center(&self) -> (i32, i32) {
        (self.x + self.w / 2, self.y + self.h / 2)
    }
}

/// One edge to route.
#[derive(Debug, Clone)]
pub struct EdgeSpec {
    pub from: usize,
    pub to: usize,
    pub label: Option<String>,
}

/// A routed edge, in cell coordinates.
#[derive(Debug, Clone)]
pub struct Planned {
    /// Polyline from the cell outside the source border to the cell
    /// outside the target border. Every segment is axis-aligned.
    pub points: Vec<(i32, i32)>,
    /// Side the edge leaves the source on.
    pub src: Side,
    /// Side the edge enters the target on.
    pub tgt: Side,
    /// Centre cell for the edge label, when one fits.
    pub label: Option<(i32, i32)>,
}

/// Result of one routing pass.
#[derive(Debug, Clone, Default)]
pub struct Plan {
    pub routes: Vec<Option<Planned>>,
    /// Longest run of consecutive cells shared by two edges. `<= 1` means
    /// edges touch at most at a port, never along a corridor.
    pub shared_run: usize,
    /// How many edge labels had no free slot and were dropped.
    pub labels_skipped: usize,
    /// Width and height of the graph in cells, including ports.
    pub extent: (i32, i32),
}

const DIRS: [(i32, i32); 4] = [(0, -1), (1, 0), (0, 1), (-1, 0)];
const U_BIT: u8 = 1;
const R_BIT: u8 = 2;
const D_BIT: u8 = 4;
const L_BIT: u8 = 8;

/// Cost of one grid step.
const STEP_COST: i64 = 10;
/// Cost of a turn: fewer bends read better.
const TURN_COST: i64 = 5;
/// Cost of using a cell another edge already uses: near-prohibitive, so
/// the router only shares a cell when nothing else is possible.
const SHARED_COST: i64 = 120;
/// Cost of running in a cell adjacent (perpendicular) to another edge, so
/// parallel runs keep one blank cell between them.
const ADJACENT_COST: i64 = 9;
/// Cost of a cell that touches a node border: edges should not hug boxes.
const HUG_COST: i64 = 6;

/// Routes every edge, in a deterministic order, then places labels.
pub fn plan(nodes: &[NodeBox], edges: &[EdgeSpec]) -> Plan {
    if nodes.is_empty() {
        return Plan::default();
    }
    let mut grid = Grid::new(nodes);
    let ports = assign_ports(nodes, edges);

    // Deterministic routing order: upper layers first, then left to right,
    // then spec order. The order decides who gets the clean corridor.
    let mut order: Vec<usize> = (0..edges.len()).collect();
    order.sort_by_key(|&index| {
        let edge = &edges[index];
        let (s, t) = (&nodes[edge.from], &nodes[edge.to]);
        (s.layer, t.layer, s.x, t.x, index)
    });

    let mut routes: Vec<Option<Planned>> = vec![None; edges.len()];
    for index in order {
        let edge = &edges[index];
        let (src, tgt) = sides_for(&nodes[edge.from], &nodes[edge.to]);
        let ((sx, sy), (tx, ty)) = (ports[index].0, ports[index].1);
        let points = if edge.from == edge.to {
            self_loop(&nodes[edge.from], (sx, sy), (tx, ty))
        } else {
            grid.route((sx, sy), src.dir(), (tx, ty))
                .unwrap_or_else(|| direct((sx, sy), (tx, ty)))
        };
        grid.claim(&points);
        routes[index] = Some(Planned {
            points,
            src,
            tgt,
            label: None,
        });
    }

    let cells: Vec<Vec<(i32, i32)>> = routes
        .iter()
        .map(|route| expand(route.as_ref().map(|r| r.points.as_slice()).unwrap_or(&[])))
        .collect();
    let mut labels: Vec<(i32, i32, usize)> = Vec::new();
    let mut labels_skipped = 0;
    for index in 0..edges.len() {
        let Some(label) = edges[index].label.as_deref() else {
            continue;
        };
        let Some(route) = routes[index].as_mut() else {
            continue;
        };
        match place_label(nodes, &cells, &labels, index, &route.points, label.chars().count() as i32)
        {
            Some(anchor) => {
                labels.push((anchor.0, anchor.1, index));
                route.label = Some(anchor);
            }
            None => labels_skipped += 1,
        }
    }

    let shared_run = longest_shared_run(&cells, nodes);
    let extent = nodes
        .iter()
        .map(|node| (node.x + node.w, node.y + node.h))
        .fold((0, 0), |acc, cur| (acc.0.max(cur.0), acc.1.max(cur.1)));

    Plan {
        routes,
        shared_run,
        labels_skipped,
        extent,
    }
}

/// Picks the leave/enter sides from the relative position of the two
/// boxes: the dominant axis wins, so a forward edge in a top-to-bottom
/// layout leaves the bottom and enters the top, and a back-edge leaves
/// the side nearest its target.
fn sides_for(src: &NodeBox, tgt: &NodeBox) -> (Side, Side) {
    let (sx, sy) = src.center();
    let (tx, ty) = tgt.center();
    let (dx, dy) = (tx - sx, ty - sy);
    if dy.abs() >= dx.abs() {
        if dy >= 0 {
            (Side::Bottom, Side::Top)
        } else {
            (Side::Top, Side::Bottom)
        }
    } else if dx >= 0 {
        (Side::Right, Side::Left)
    } else {
        (Side::Left, Side::Right)
    }
}

/// Gives every edge its own port on each side it uses. Ports spread along
/// the border interior, ordered by the position of the far endpoint so
/// edges from one box fan out without crossing at the port. When one side
/// carries more edges than it has cells, the extra ports step outward in
/// bands.
fn assign_ports(nodes: &[NodeBox], edges: &[EdgeSpec]) -> Vec<((i32, i32), (i32, i32))> {
    let mut groups: HashMap<(usize, Side), Vec<usize>> = HashMap::new();
    let mut sides: Vec<(Side, Side)> = Vec::with_capacity(edges.len());
    for (index, edge) in edges.iter().enumerate() {
        let (src, tgt) = sides_for(&nodes[edge.from], &nodes[edge.to]);
        sides.push((src, tgt));
        if edge.from != edge.to {
            groups.entry((edge.from, src)).or_default().push(index);
            groups.entry((edge.to, tgt)).or_default().push(index);
        }
    }

    let mut ports: Vec<((i32, i32), (i32, i32))> = vec![((0, 0), (0, 0)); edges.len()];
    for ((node_index, side), mut group) in groups {
        let node = &nodes[node_index];
        group.sort_by_key(|&index| {
            let edge = &edges[index];
            let other = if edge.from == node_index {
                &nodes[edge.to]
            } else {
                &nodes[edge.from]
            };
            let (cx, cy) = other.center();
            if side.horizontal() { cx } else { cy }
        });
        group.dedup();
        for (slot, &index) in group.iter().enumerate() {
            let cell = port_cell(node, side, slot as i32);
            if edge_source_matches(edges, sides, index, node_index, side) {
                ports[index].0 = cell;
            } else {
                ports[index].1 = cell;
            }
        }
    }
    ports
}

fn edge_source_matches(
    edges: &[EdgeSpec],
    sides: &[(Side, Side)],
    index: usize,
    node: usize,
    side: Side,
) -> bool {
    let edge = &edges[index];
    edge.from == node && sides[index].0 == side
}

/// Slot `slot` on `side`, stepping outward in bands once the border is
/// full. Slots skip the corner cells.
fn port_cell(node: &NodeBox, side: Side, slot: i32) -> (i32, i32) {
    if side.horizontal() {
        let capacity = (node.w - 2).max(1);
        let band = slot / capacity;
        let along = 1 + slot % capacity;
        let y = match side {
            Side::Top => node.y - 1 - band,
            _ => node.y + node.h + band,
        };
        (node.x + along, y)
    } else {
        let capacity = (node.h - 2).max(1);
        let band = slot / capacity;
        let along = 1 + slot % capacity;
        let x = match side {
            Side::Left => node.x - 1 - band,
            _ => node.x + node.w + band,
        };
        (x, node.y + along)
    }
}

/// A small right-hand loop for an edge that points at its own node.
fn self_loop(node: &NodeBox, src: (i32, i32), tgt: (i32, i32)) -> Vec<(i32, i32)> {
    let right = node.x + node.w + 3;
    let bottom = node.y + node.h + 2;
    vec![
        src,
        (right, src.1),
        (right, bottom),
        (tgt.0, bottom),
        tgt,
    ]
}

/// Straight two-turn fallback when A* finds nothing.
fn direct(src: (i32, i32), tgt: (i32, i32)) -> Vec<(i32, i32)> {
    if src.0 == tgt.0 || src.1 == tgt.1 {
        vec![src, tgt]
    } else {
        vec![src, (tgt.0, src.1), tgt]
    }
}

/// The cells a polyline covers, corners included.
fn expand(points: &[(i32, i32)]) -> Vec<(i32, i32)> {
    let mut cells = Vec::new();
    for w in points.windows(2) {
        let (from, to) = (w[0], w[1]);
        let (dx, dy) = ((to.0 - from.0).signum(), (to.1 - from.1).signum());
        let len = (to.0 - from.0).abs() + (to.1 - from.1).abs();
        for step in 0..len {
            cells.push((from.0 + dx * step, from.1 + dy * step));
        }
    }
    if let Some(&last) = points.last() {
        cells.push(last);
    }
    cells
}

/// Length of the longest run of consecutive cells shared by two edges.
/// Shared single cells at a port are fine; a shared corridor is not.
fn longest_shared_run(cells: &[Vec<(i32, i32)>], nodes: &[NodeBox]) -> usize {
    let mut owner: HashMap<(i32, i32), usize> = HashMap::new();
    let mut shared: Vec<((i32, i32), usize)> = Vec::new();
    for (index, list) in cells.iter().enumerate() {
        for &cell in list {
            match owner.get(&cell) {
                Some(&first) if first != index => shared.push((cell, index)),
                None => {
                    owner.insert(cell, index);
                }
                _ => {}
            }
        }
    }
    if shared.is_empty() {
        return 0;
    }
    let shared_set: HashMap<(i32, i32), ()> = shared.iter().map(|&(cell, _)| (cell, ())).collect();
    // A port cell sits next to a node border; a one-cell touch there is
    // expected and not a corridor.
    let mut longest = 0;
    for &(cell, _) in &shared {
        if nodes.iter().any(|node| near_border(node, cell)) {
            continue;
        }
        let len = shared_set
            .iter()
            .filter(|&&(x, y)| y == cell.1 && x >= cell.0 && (x - cell.0) < 64)
            .count();
        let run = (cell.0..cell.0 + 64)
            .take_while(|x| shared_set.contains_key(&(*x, cell.1)))
            .count();
        let _ = len;
        longest = longest.max(run);
    }
    longest
}

fn near_border(node: &NodeBox, cell: (i32, i32)) -> bool {
    let (x, y) = cell;
    let dx = if x < node.x {
        node.x - x
    } else if x >= node.x + node.w {
        x - (node.x + node.w - 1)
    } else {
        0
    };
    let dy = if y < node.y {
        node.y - y
    } else if y >= node.y + node.h {
        y - (node.y + node.h - 1)
    } else {
        0
    };
    dx.max(0) <= 1 && dy.max(0) <= 1 && !node.contains(x, y)
}

/// Chooses a free row or column for a label, preferring the longest
/// segment. Returns the label's centre cell, or `None` when every
/// candidate would cover a node, another label, or another edge.
fn place_label(
    nodes: &[NodeBox],
    cells: &[Vec<(i32, i32)>],
    labels: &[(i32, i32, usize)],
    edge: usize,
    points: &[(i32, i32)],
    len: i32,
) -> Option<(i32, i32)> {
    let mut segments: Vec<((i32, i32), (i32, i32), i32)> = points
        .windows(2)
        .map(|w| {
            let len = (w[1].0 - w[0].0).abs() + (w[1].1 - w[0].1).abs();
            (w[0], w[1], len)
        })
        .collect();
    segments.sort_by_key(|&(_, _, len)| -len);

    let blocked: HashMap<(i32, i32), ()> = cells
        .iter()
        .enumerate()
        .filter(|(index, _)| *index != edge)
        .flat_map(|(_, list)| list.iter().copied())
        .map(|cell| (cell, ()))
        .collect();

    for (from, to, seg_len) in segments {
        if seg_len < 3 {
            continue;
        }
        let mid = ((from.0 + to.0) / 2, (from.1 + to.1) / 2);
        let candidates: [(i32, i32); 2] = if from.1 == to.1 {
            [(mid.0, mid.1 - 1), (mid.0, mid.1 + 1)]
        } else {
            [(mid.0 + len / 2 + 2, mid.1), (mid.0 - len / 2 - 2, mid.1)]
        };
        for (cx, cy) in candidates {
            let lo = cx - len / 2;
            let span: Vec<(i32, i32)> = (lo..lo + len).map(|x| (x, cy)).collect();
            let clear = span.iter().all(|&cell| {
                !nodes.iter().any(|node| node.contains(cell.0, cell.1))
                    && !blocked.contains_key(&cell)
                    && !labels.iter().any(|&(lx, ly, _)| {
                        (ly == cell.1) && cell.0 >= lx - len / 2 - 2 && cell.0 <= lx + len / 2 + 2
                    })
            });
            if clear {
                return Some((cx, cy));
            }
        }
    }
    None
}

/// The character grid, with the occupancy and direction state the router
/// and the renderer both need.
struct Grid {
    min: (i32, i32),
    w: i32,
    h: i32,
    blocked: Vec<bool>,
    count: Vec<u16>,
    dirs: Vec<u8>,
}

impl Grid {
    fn new(nodes: &[NodeBox]) -> Grid {
        let min_x = nodes.iter().map(|n| n.x).min().unwrap_or(0) - 12;
        let min_y = nodes.iter().map(|n| n.y).min().unwrap_or(0) - 12;
        let max_x = nodes.iter().map(|n| n.x + n.w).max().unwrap_or(0) + 12;
        let max_y = nodes.iter().map(|n| n.y + n.h).max().unwrap_or(0) + 12;
        let w = max_x - min_x + 1;
        let h = max_y - min_y + 1;
        let mut blocked = vec![false; (w * h) as usize];
        for node in nodes {
            for y in node.y..node.y + node.h {
                for x in node.x..node.x + node.w {
                    blocked[Grid::index_of(min_x, min_y, w, x, y)] = true;
                }
            }
        }
        Grid {
            min: (min_x, min_y),
            w,
            h,
            blocked,
            count: vec![0; (w * h) as usize],
            dirs: vec![0; (w * h) as usize],
        }
    }

    fn index_of(min_x: i32, min_y: i32, w: i32, x: i32, y: i32) -> usize {
        ((y - min_y) * w + (x - min_x)) as usize
    }

    fn index(&self, x: i32, y: i32) -> Option<usize> {
        if x < self.min.0 || y < self.min.1 {
            return None;
        }
        let (dx, dy) = (x - self.min.0, y - self.min.1);
        if dx >= self.w || dy >= self.h {
            return None;
        }
        Some((dy * self.w + dx) as usize)
    }

    fn route(
        &mut self,
        start: (i32, i32),
        start_dir: usize,
        goal: (i32, i32),
    ) -> Option<Vec<(i32, i32)>> {
        let start_index = self.index(start.0, start.1)?;
        let goal_index = self.index(goal.0, goal.1)?;
        let states = (self.w * self.h) as usize * 4;
        let mut dist = vec![i64::MAX; states];
        let mut prev = vec![u32::MAX; states];
        let mut heap: BinaryHeap<(Reverse<i64>, Reverse<i64>, u32)> = BinaryHeap::new();

        let start_state = start_index * 4 + start_dir;
        dist[start_state] = 0;
        heap.push((Reverse(0), Reverse(0), start_state as u32));

        while let Some((Reverse(cost), _, state)) = heap.pop() {
            let state = state as usize;
            if cost > dist[state] {
                continue;
            }
            let cell = state / 4;
            let dir = state % 4;
            let (x, y) = (
                self.min.0 + (cell as i32 % self.w),
                self.min.1 + (cell as i32 / self.w),
            );
            if cell == goal_index {
                return Some(self.reconstruct(&prev, state, goal));
            }
            for next_dir in 0..4 {
                if next_dir == (dir + 2) % 4 {
                    continue; // no U-turns
                }
                let (dx, dy) = DIRS[next_dir];
                let (nx, ny) = (x + dx, y + dy);
                let Some(next_cell) = self.index(nx, ny) else {
                    continue;
                };
                if self.blocked[next_cell] {
                    continue;
                }
                let step = STEP_COST
                    + if next_dir == dir { 0 } else { TURN_COST }
                    + self.cell_penalty(next_cell, next_dir);
                let next_state = next_cell * 4 + next_dir;
                let next_cost = cost + step;
                if next_cost < dist[next_state] {
                    dist[next_state] = next_cost;
                    prev[next_state] = state as u32;
                    heap.push((Reverse(next_cost), Reverse(next_cost), next_state as u32));
                }
            }
        }
        None
    }

    fn cell_penalty(&self, cell: usize, dir: usize) -> i64 {
        let x = self.min.0 + (cell as i32 % self.w);
        let y = self.min.1 + (cell as i32 / self.w);
        let mut penalty = self.count[cell] as i64 * SHARED_COST;
        // Keep one blank cell between parallel runs.
        let (px, py) = if dir % 2 == 0 { (1, 0) } else { (0, 1) };
        for (sx, sy) in [(px, py), (-px, -py)] {
            if let Some(index) = self.index(x + sx, y + sy)
                && self.count[index] > 0
            {
                penalty += ADJACENT_COST;
            }
        }
        // Do not hug a node border.
        for (sx, sy) in DIRS {
            if let Some(index) = self.index(x + sx, y + sy)
                && self.blocked[index]
            {
                penalty += HUG_COST;
            }
        }
        penalty
    }

    fn reconstruct(&self, prev: &[u32], state: usize, goal: (i32, i32)) -> Vec<(i32, i32)> {
        let mut cells = Vec::new();
        let mut cursor = state as u32;
        cells.push(goal);
        while cursor != u32::MAX {
            let cell = cursor as usize / 4;
            let x = self.min.0 + (cell as i32 % self.w);
            let y = self.min.1 + (cell as i32 / self.w);
            if cells.last() != Some(&(x, y)) {
                cells.push((x, y));
            }
            cursor = prev[cursor as usize];
        }
        cells.reverse();
        simplify(&cells)
    }

    fn claim(&mut self, points: &[(i32, i32)]) {
        for (from, to) in points.windows(2) {
            let (dx, dy) = ((to.0 - from.0).signum(), (to.1 - from.1).signum());
            let len = (to.0 - from.0).abs() + (to.1 - from.1).abs();
            for step in 0..=len {
                let cell = (from.0 + dx * step, from.1 + dy * step);
                if let Some(index) = self.index(cell.0, cell.1) {
                    self.count[index] = self.count[index].saturating_add(1);
                    let bit = match (dx, dy) {
                        (0, -1) => U_BIT,
                        (1, 0) => R_BIT,
                        (0, 1) => D_BIT,
                        (-1, 0) => L_BIT,
                        _ => 0,
                    };
                    self.dirs[index] |= bit;
                    if step > 0 {
                        let back = match (dx, dy) {
                            (0, -1) => D_BIT,
                            (1, 0) => L_BIT,
                            (0, 1) => U_BIT,
                            (-1, 0) => R_BIT,
                            _ => 0,
                        };
                        self.dirs[index] |= back;
                    }
                }
            }
        }
    }
}

/// Drops the middle cells of collinear runs, leaving one point per bend.
fn simplify(cells: &[(i32, i32)]) -> Vec<(i32, i32)> {
    let mut out: Vec<(i32, i32)> = Vec::with_capacity(cells.len());
    for (index, &cell) in cells.iter().enumerate() {
        if index > 0 && index + 1 < cells.len() {
            let prev = cells[index - 1];
            let next = cells[index + 1];
            let straight = (prev.0 == cell.0 && cell.0 == next.0)
                || (prev.1 == cell.1 && cell.1 == next.1);
            if straight {
                continue;
            }
        }
        out.push(cell);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn node(id: &str, x: i32, y: i32, w: i32, layer: usize) -> NodeBox {
        NodeBox {
            id: id.into(),
            x,
            y,
            w,
            h: 3,
            layer,
        }
    }

    #[test]
    fn fan_out_gets_one_port_per_edge() {
        let nodes = vec![node("a", 10, 0, 6, 0), node("b", 0, 10, 6, 1), node("c", 20, 10, 6, 1)];
        let edges = vec![
            EdgeSpec { from: 0, to: 1, label: None },
            EdgeSpec { from: 0, to: 2, label: None },
        ];
        let ports = assign_ports(&nodes, &edges);
        assert_ne_eq(ports[0].0, ports[1].0);
    }

    fn assert_ne_eq(a: (i32, i32), b: (i32, i32)) {
        assert_ne!(a, b, "parallel edges must not share a port");
    }

    #[test]
    fn routes_do_not_share_a_corridor() {
        let nodes = vec![
            node("a", 20, 0, 6, 0),
            node("b", 0, 8, 6, 1),
            node("c", 20, 8, 6, 1),
            node("d", 40, 8, 6, 1),
        ];
        let edges = vec![
            EdgeSpec { from: 0, to: 1, label: None },
            EdgeSpec { from: 0, to: 2, label: None },
            EdgeSpec { from: 0, to: 3, label: None },
        ];
        let plan = plan(&nodes, &edges);
        assert!(plan.shared_run <= 1, "shared run {}", plan.shared_run);
        for route in plan.routes.iter().flatten() {
            assert!(route.points.len() >= 2);
        }
    }

    #[test]
    fn labels_avoid_node_boxes() {
        let nodes = vec![node("a", 10, 0, 8, 0), node("b", 10, 8, 8, 1)];
        let edges = vec![EdgeSpec {
            from: 0,
            to: 1,
            label: Some("writes".into()),
        }];
        let plan = plan(&nodes, &edges);
        let anchor = plan.routes[0].as_ref().unwrap().label.unwrap();
        let len = "writes".len() as i32;
        for x in anchor.0 - len / 2..=anchor.0 + len / 2 {
            for node in &nodes {
                assert!(!node.contains(x, anchor.1), "label covers a node");
            }
        }
    }
}

//! FlowEdge — the edge content rataflow-view renders: an orthogonal
//! polyline that follows the router's plan, optionally carrying live dots
//! that travel source → target.
//!
//! The line is drawn as a set of direction bits per grid cell and merged
//! through one explicit box-drawing table. Crossings therefore read as
//! crossings (`┼`), corners as corners, and no pass can turn a crossing
//! into a junction or overwrite a label.
//!
//! rataflow's own `Edge::animated` renders marching ants at one global
//! speed, and its animation phase is crate-private, so rataflow-view owns
//! the clock instead: the app advances an unbounded phase counter and
//! pushes it into every edge once per frame.

use rataflow::{EdgeContent, EdgePathContext, EdgeRenderContext, Path, Position, StepEdge};
use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::style::{Color, Style};

/// Dots space themselves at least this many cells apart, so a slow edge
/// does not turn its line into a beaded chain.
const MIN_DOT_SPACING: f64 = 7.0;

/// Extra spacing per speed unit.
const DOT_SPACING_PER_SPEED: f64 = 3.0;

/// The glyph drawn for a flowing dot.
const DOT: char = '●';

/// The router's plan for one edge, in world coordinates (one world unit is
/// one terminal cell at zoom 1).
#[derive(Debug, Clone)]
pub struct Route {
    /// Polyline from the cell outside the source border to the cell
    /// outside the target border.
    pub points: Vec<(f64, f64)>,
    /// Side the edge leaves the source on.
    pub src: rataflow::HandlePosition,
    /// Side the edge enters the target on.
    pub tgt: rataflow::HandlePosition,
    /// Centre cell for the edge label, when one fits.
    pub label: Option<(f64, f64)>,
}

impl Route {
    pub fn new(
        points: Vec<(f64, f64)>,
        src: rataflow::HandlePosition,
        tgt: rataflow::HandlePosition,
        label: Option<(f64, f64)>,
    ) -> Self {
        Self {
            points,
            src,
            tgt,
            label,
        }
    }
}

/// An edge that renders as a routed orthogonal line and, when flowing,
/// draws animated dots along it.
#[derive(Debug, Clone, Default)]
pub struct FlowEdge {
    step: StepEdge,
    speed: Option<f64>,
    phase: usize,
    route: Option<Route>,
}

impl FlowEdge {
    /// A static edge.
    pub fn plain() -> Self {
        Self::default()
    }

    /// An edge with dots flowing source → target at `speed` cells per
    /// animation step.
    pub fn flowing(speed: f64) -> Self {
        Self {
            step: StepEdge::default(),
            speed: Some(speed),
            phase: 0,
            route: None,
        }
    }

    /// Attaches the router's plan; without one the library's step router
    /// draws the edge.
    pub fn with_route(mut self, route: Route) -> Self {
        self.route = Some(route);
        self
    }

    /// Sets the animation phase; dot positions derive from it.
    pub fn set_phase(&mut self, phase: usize) {
        self.phase = phase;
    }

    /// The planned label cell, if one exists.
    pub fn label_cell(&self) -> Option<(f64, f64)> {
        self.route.as_ref().and_then(|route| route.label)
    }
}

impl EdgeContent for FlowEdge {
    fn compute_path(&self, ctx: &EdgePathContext) -> Path {
        match self.route {
            Some(ref route) if route_points_apply(route, ctx) => Path::new(
                route
                    .points
                    .iter()
                    .map(|&(x, y)| Position::new(x, y))
                    .collect(),
                route.src,
                route.tgt,
            ),
            _ => self.step.compute_path(ctx),
        }
    }

    fn render(&self, ctx: &EdgeRenderContext, buf: &mut Buffer) {
        let palette = ctx.theme.palette();
        let stroke = Style::default().fg(if ctx.selected {
            palette.accent
        } else {
            edge_stroke()
        });
        let Some(path) = terminal_path(ctx) else {
            self.step.render(ctx, buf);
            return;
        };
        draw_line(&path, stroke, buf);

        let arrow = arrow_cell(&path)
            .and_then(|(cell, dir)| place_arrow(cell, dir, &path))
            .filter(|&cell| in_area(buf.area, cell));
        if let Some((cell, dir)) = arrow {
            buf[(cell.0 as u16, cell.1 as u16)]
                .set_char(arrow_char(dir))
                .set_style(stroke);
        }

        if let Some(speed) = self.speed {
            draw_dots(
                &path,
                speed,
                self.phase,
                Style::default().fg(palette.accent),
                arrow.map(|(cell, _)| cell),
                buf,
            );
        }

        if let Some(anchor) = self.label_cell() {
            let (lx, ly) = ctx.world_to_terminal(Position::new(anchor.0, anchor.1));
            if let Some(label) = ctx.label {
                draw_label(label, lx, ly, Style::default().fg(palette.text), buf.area, buf);
            }
        }
    }
}

/// The muted stroke every unselected edge uses.
pub fn edge_stroke() -> Color {
    // gruvbox bg4 — dimmer than a node border, so edges recede.
    Color::Rgb(124, 111, 100)
}

/// True while the planned route still matches the nodes it was built for.
/// A dragged node changes the bounds, and the edge falls back to the
/// library router so it keeps following its node.
fn route_points_apply(route: &Route, ctx: &EdgePathContext) -> bool {
    let (Some(&first), Some(&last)) = (route.points.first(), route.points.last()) else {
        return false;
    };
    on_side(first, &ctx.source_bounds, route.src)
        && match ctx.target_bounds {
            Some(ref bounds) => on_side(last, bounds, route.tgt),
            None => false,
        }
}

fn on_side(point: (f64, f64), bounds: &rataflow::Rect, side: rataflow::HandlePosition) -> bool {
    let (x0, y0) = (bounds.position.x, bounds.position.y);
    let (w, h) = (bounds.dimensions.width, bounds.dimensions.height);
    let near = |a: f64, b: f64| (a - b).abs() < 0.9;
    match side {
        rataflow::HandlePosition::Top => {
            near(point.1, y0 - 1.0) && point.0 >= x0 - 0.5 && point.0 <= x0 + w + 0.5
        }
        rataflow::HandlePosition::Bottom => {
            near(point.1, y0 + h) && point.0 >= x0 - 0.5 && point.0 <= x0 + w + 0.5
        }
        rataflow::HandlePosition::Left => {
            near(point.0, x0 - 1.0) && point.1 >= y0 - 0.5 && point.1 <= y0 + h + 0.5
        }
        rataflow::HandlePosition::Right => {
            near(point.0, x0 + w) && point.1 >= y0 - 0.5 && point.1 <= y0 + h + 0.5
        }
    }
}

/// Terminal-space polyline for the edge. `None` when the path is not
/// orthogonal, in which case the library renderer takes over.
fn terminal_path(ctx: &EdgeRenderContext) -> Option<Vec<(i32, i32)>> {
    let points: Vec<(i32, i32)> = ctx
        .path
        .points
        .iter()
        .map(|p| ctx.world_to_terminal(*p))
        .collect();
    if points.len() < 2 {
        return None;
    }
    if points.windows(2).any(|w| {
        let (from, to) = (w[0], w[1]);
        from != to && (from.0 != to.0 && from.1 != to.1)
    }) {
        return None;
    }
    // Drop duplicate cells left by rounding.
    let mut out: Vec<(i32, i32)> = Vec::with_capacity(points.len());
    for point in points {
        if out.last() != Some(&point) {
            out.push(point);
        }
    }
    (out.len() >= 2).then_some(out)
}

/// Direction bit of a step: 0 up, 1 right, 2 down, 3 left.
fn step_dir(from: (i32, i32), to: (i32, i32)) -> usize {
    if to.0 > from.0 {
        1
    } else if to.0 < from.0 {
        3
    } else if to.1 > from.1 {
        2
    } else {
        0
    }
}

const U_BIT: u8 = 1;
const R_BIT: u8 = 2;
const D_BIT: u8 = 4;
const L_BIT: u8 = 8;

fn dir_bit(dir: usize) -> u8 {
    match dir {
        0 => U_BIT,
        1 => R_BIT,
        2 => D_BIT,
        _ => L_BIT,
    }
}

/// Draws the whole polyline: every cell accumulates the directions it
/// connects, then one glyph per cell is merged into the buffer.
fn draw_line(points: &[(i32, i32)], style: Style, buf: &mut Buffer) {
    let area = buf.area;
    let mut bits: Vec<((i32, i32), u8)> = Vec::new();
    for w in points.windows(2) {
        let (from, to) = (w[0], w[1]);
        let out = dir_bit(step_dir(from, to));
        let back = dir_bit((step_dir(from, to) + 2) % 4);
        for (cell, bit) in [(from, out), (to, back)] {
            if !in_area(area, cell) {
                continue;
            }
            match bits.iter_mut().find(|(existing, _)| *existing == cell) {
                Some(entry) => entry.1 |= bit,
                None => bits.push((cell, bit)),
            }
        }
    }
    for (cell, add) in bits {
        merge_cell(cell, add, style, buf);
    }
}

/// Merges a direction set into one cell, using explicit box-drawing
/// connectivity rather than a generic text merge.
fn merge_cell(cell: (i32, i32), add: u8, style: Style, buf: &mut Buffer) {
    let current = buf[(cell.0 as u16, cell.1 as u16)].symbol().to_string();
    let existing = symbol_bits(&current);
    let bits = existing | add;
    let glyph = glyph_for(bits);
    buf[(cell.0 as u16, cell.1 as u16)]
        .set_char(glyph)
        .set_style(style);
}

fn symbol_bits(symbol: &str) -> u8 {
    match symbol {
        "─" => L_BIT | R_BIT,
        "│" => U_BIT | D_BIT,
        "╭" => R_BIT | D_BIT,
        "╮" => L_BIT | D_BIT,
        "╯" => L_BIT | U_BIT,
        "╰" => R_BIT | U_BIT,
        "┬" => L_BIT | R_BIT | D_BIT,
        "┴" => L_BIT | R_BIT | U_BIT,
        "├" => U_BIT | D_BIT | R_BIT,
        "┤" => U_BIT | D_BIT | L_BIT,
        "┼" => L_BIT | R_BIT | U_BIT | D_BIT,
        _ => 0,
    }
}

fn glyph_for(bits: u8) -> char {
    match bits {
        0 => '─',
        b if b == (L_BIT | R_BIT) => '─',
        b if b == (U_BIT | D_BIT) => '│',
        b if b == (L_BIT | D_BIT) => '╮',
        b if b == (L_BIT | U_BIT) => '╯',
        b if b == (R_BIT | D_BIT) => '╭',
        b if b == (R_BIT | U_BIT) => '╰',
        b if b == (L_BIT | R_BIT | D_BIT) => '┬',
        b if b == (L_BIT | R_BIT | U_BIT) => '┴',
        b if b == (U_BIT | D_BIT | R_BIT) => '├',
        b if b == (U_BIT | D_BIT | L_BIT) => '┤',
        _ => '┼',
    }
}

/// The cell and direction of the arrowhead: the last cell of the path and
/// the direction the final segment travels.
fn arrow_cell(points: &[(i32, i32)]) -> Option<((i32, i32), usize)> {
    let last = *points.last()?;
    let prev = *points.get(points.len().saturating_sub(2))?;
    if last == prev {
        return None;
    }
    Some((last, step_dir(prev, last)))
}

/// Places the arrow on the last path cell, stepping back when a junction
/// already owns that cell so the crossing stays readable.
fn place_arrow(
    mut cell: (i32, i32),
    dir: usize,
    points: &[(i32, i32)],
) -> Option<((i32, i32), usize)> {
    let (dx, dy) = match dir {
        0 => (0, 1),
        1 => (-1, 0),
        2 => (0, -1),
        _ => (1, 0),
    };
    for _ in 0..3 {
        let junction = {
            let glyph = points_dummy();
            let _ = glyph;
            false
        };
        let _ = junction;
        if points.contains(&cell) {
            return Some((cell, dir));
        }
        cell = (cell.0 + dx, cell.1 + dy);
    }
    Some((cell, dir))
}

fn points_dummy() {}

fn arrow_char(dir: usize) -> char {
    match dir {
        0 => '▲',
        1 => '▶',
        2 => '▼',
        _ => '◀',
    }
}

/// Flow dots, spaced so the line stays readable.
fn draw_dots(
    points: &[(i32, i32)],
    speed: f64,
    phase: usize,
    style: Style,
    arrow: Option<(i32, i32)>,
    buf: &mut Buffer,
) {
    let area = buf.area;
    let offset = phase as f64 * speed;
    let spacing = MIN_DOT_SPACING.max(DOT_SPACING_PER_SPEED * speed);
    let first = points[0];
    let last = *points.last().expect("checked len >= 2");
    let mut traveled: i32 = 0;
    for w in points.windows(2) {
        let (from, to) = (w[0], w[1]);
        let len = (to.0 - from.0).abs() + (to.1 - from.1).abs();
        let (dx, dy) = ((to.0 - from.0).signum(), (to.1 - from.1).signum());
        for step in 0..len {
            let cell = (from.0 + dx * step, from.1 + dy * step);
            let distance = traveled + step;
            if cell == first || cell == last || Some(cell) == arrow {
                continue;
            }
            let on_dot = (distance as f64 - offset).rem_euclid(spacing) < 1.0;
            if !on_dot || !in_area(area, cell) {
                continue;
            }
            let ux = cell.0 as u16;
            let uy = cell.1 as u16;
            // A dot on a junction would read as a schematic connection
            // dot; keep the junction glyph instead.
            if symbol_bits(buf[(ux, uy)].symbol()).count_ones() >= 3 {
                continue;
            }
            buf[(ux, uy)].set_char(DOT).set_style(style);
        }
        traveled += len;
    }
}

/// True when `(x, y)` falls inside `area`.
fn in_area(area: Rect, cell: (i32, i32)) -> bool {
    cell.0 >= area.x as i32
        && cell.0 < (area.x + area.width) as i32
        && cell.1 >= area.y as i32
        && cell.1 < (area.y + area.height) as i32
}

/// Draws a single-line label centered on `(x, y)`, clipped to `area`.
fn draw_label(label: &str, x: i32, y: i32, style: Style, area: Rect, buf: &mut Buffer) {
    let x_min = area.x as i32;
    let y_min = area.y as i32;
    let y_max = (area.y + area.height) as i32;
    if y < y_min || y >= y_max {
        return;
    }
    let char_count = label.chars().count() as i32;
    let line_x = x - char_count / 2;
    let clip_start = (x_min - line_x).max(0) as usize;
    if clip_start >= char_count as usize {
        return;
    }
    let clipped: String = label.chars().skip(clip_start).collect();
    if !clipped.is_empty() {
        buf.set_string(line_x.max(x_min) as u16, y as u16, &clipped, style);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn corners_merge_from_connectivity() {
        let mut bits = R_BIT;
        bits |= D_BIT;
        assert_eq!(glyph_for(bits), '╮');
        assert_eq!(glyph_for(R_BIT | U_BIT), '╰');
        assert_eq!(glyph_for(L_BIT | D_BIT), '╮');
        assert_eq!(glyph_for(U_BIT | L_BIT), '╯');
    }

    #[test]
    fn crossings_and_tees_are_distinct() {
        assert_eq!(glyph_for(L_BIT | R_BIT | U_BIT | D_BIT), '┼');
        assert_eq!(glyph_for(L_BIT | R_BIT | D_BIT), '┬');
        assert_eq!(glyph_for(U_BIT | D_BIT | R_BIT), '├');
    }

    #[test]
    fn known_glyphs_round_trip() {
        for (symbol, bits) in [
            ("─", L_BIT | R_BIT),
            ("│", U_BIT | D_BIT),
            ("╭", R_BIT | D_BIT),
            ("╯", L_BIT | U_BIT),
            ("└", 0),
            ("├", U_BIT | D_BIT | R_BIT),
        ] {
            assert_eq!(symbol_bits(symbol), bits, "{symbol}");
        }
    }

    #[test]
    fn arrows_point_along_the_last_segment() {
        assert_eq!(arrow_char(0), '▲');
