/// already owns that cell so the crossing stays readable.
fn place_arrow(
    mut cell: (i32, i32),
    dir: usize,
    points: &[(i32, i32)],
    buf: &Buffer,
) -> Option<((i32, i32), usize)> {
    let (dx, dy) = match dir {
        0 => (0, 1),
        1 => (-1, 0),
        2 => (0, -1),
        _ => (1, 0),
    };
    for _ in 0..3 {
        if !in_area(buf.area, cell) {
            return None;
        }
        let junction = symbol_bits(buf[(cell.0 as u16, cell.1 as u16)].symbol()).count_ones() >= 3;
        if !junction && points.contains(&cell) {
            return Some((cell, dir));
        }
        cell = (cell.0 + dx, cell.1 + dy);
    }
    None
}

