            (
                self.border_style
                    .unwrap_or_else(|| Style::default().fg(palette.muted)),
                self.text_style
                    .unwrap_or_else(|| Style::default().fg(palette.text)),
                self.background.unwrap_or(Some(palette.surface)),
            )
        }
    }

