    ///
    /// Returns the position at the node's edge in world coordinates.
    pub fn absolute_position(&self, node_pos: &Position, node_dims: &Dimensions) -> Position {
        match self.position {
            HandlePosition::Top => {
                Position::new(node_pos.x + node_dims.width * self.offset, node_pos.y)
