/// Routes every edge, in a deterministic order, then places labels.
pub fn plan(nodes: &[NodeBox], edges: &[EdgeSpec], axis: FlowAxis) -> Plan {
    if nodes.is_empty() {
        return Plan::default();
    }
    let mut grid = Grid::new(nodes);
    let ports = assign_ports(nodes, edges, axis);

    // Deterministic routing order: upper layers first, then left to right,
    // then spec order. The order decides who gets the clean corridor.
    let mut order: Vec<usize> = (0..edges.len()).collect();
    order.sort_by_key(|&index| {
        let edge = &edges[index];
        let (s, t) = (&nodes[edge.from], &nodes[edge.to]);
        (s.layer, t.layer, s.x, t.x, index)
    });

    let mut routes: Vec<Option<Planned>> = vec![None; edges.len()];
    for index in order {
        let edge = &edges[index];
        let (src, tgt) = sides_for(&nodes[edge.from], &nodes[edge.to], axis);
        let ((sx, sy), (tx, ty)) = (ports[index].0, ports[index].1);
        let points = if edge.from == edge.to {
            self_loop(&nodes[edge.from], (sx, sy), (tx, ty))
        } else {
            // Arrive against the target side, so the arrow points into the
            // box instead of sliding along its border.
            let arrive = (tgt.dir() + 2) % 4;
            // A forward edge never travels backward along the flow, and a
            // back-edge never travels forward: that single rule removes the
            // down-then-up jog that made routes look arbitrary.
            let against = if edge_backward(&nodes[edge.from], &nodes[edge.to], axis) {
                Some(match axis {
                    FlowAxis::TopToBottom => 2, // no downward step
                    FlowAxis::LeftToRight => 1, // no rightward step
                })
            } else if edge_forward(&nodes[edge.from], &nodes[edge.to], axis) {
                Some(match axis {
                    FlowAxis::TopToBottom => 0, // no upward step
                    FlowAxis::LeftToRight => 3, // no leftward step
                })
            } else {
                None
            };
            grid.route((sx, sy), src.dir(), (tx, ty), arrive, against)
                .unwrap_or_else(|| direct((sx, sy), (tx, ty)))
        };
        grid.claim(&points);
        routes[index] = Some(Planned {
            points,
            src,
            tgt,
            label: None,
        });
    }

    let axes: Vec<Vec<((i32, i32), u8)>> = routes
        .iter()
        .map(|route| expand_axes(route.as_ref().map(|r| r.points.as_slice()).unwrap_or(&[])))
        .collect();
    let cells: Vec<Vec<(i32, i32)>> = axes
        .iter()
        .map(|list| list.iter().map(|&(cell, _)| cell).collect())
        .collect();
    let max_x = nodes.iter().map(|n| n.x + n.w).max().unwrap_or(0);
    let max_y = nodes.iter().map(|n| n.y + n.h).max().unwrap_or(0);
    let mut labels: Vec<(i32, i32, usize)> = Vec::new();
    let mut labels_skipped = 0;
    for index in 0..edges.len() {
        let Some(label) = edges[index].label.as_deref() else {
            continue;
        };
        let Some(route) = routes[index].as_mut() else {
            continue;
        };
        match place_label(
            nodes,
            &cells,
            &labels,
            index,
            &route.points,
            label.chars().count() as i32,
            (max_x, max_y),
        ) {
            Some(anchor) => {
                labels.push((anchor.0, anchor.1, index));
                route.label = Some(anchor);
            }
            None => labels_skipped += 1,
        }
    }

    let shared_run = longest_shared_run(&axes, nodes);
    let extent = nodes
        .iter()
        .map(|node| (node.x + node.w, node.y + node.h))
        .fold((0, 0), |acc, cur| (acc.0.max(cur.0), acc.1.max(cur.1)));

    Plan {
        routes,
        shared_run,
        labels_skipped,
        extent,
    }
}

/// Picks the leave/enter sides from the relative position of the two
/// boxes: the dominant axis wins, so a forward edge in a top-to-bottom
/// layout leaves the bottom and enters the top, and a back-edge leaves
/// the side nearest its target.
fn sides_for(src: &NodeBox, tgt: &NodeBox, axis: FlowAxis) -> (Side, Side) {
    // A forward edge follows the layout's flow, even when the boxes are
    // far apart sideways: a sideways entry in a top-to-bottom chart reads
    // as a different relationship.
    if tgt.layer > src.layer {
        return match axis {
            FlowAxis::TopToBottom => (Side::Bottom, Side::Top),
            FlowAxis::LeftToRight => (Side::Right, Side::Left),
        };
    }
    if tgt.layer < src.layer {
        // A back-edge is a return path. Send it out of the side that faces
        // away from the flow, and let it come back in on the same side:
        // it then runs around the diagram instead of crossing the middle.
        let outward = if tgt.center().0 <= src.center().0 {
            Side::Left
        } else {
            Side::Right
        };
        return (outward, outward);
    }
    let (sx, sy) = src.center();
    let (tx, ty) = tgt.center();
    let (dx, dy) = (tx - sx, ty - sy);
    if dy.abs() >= dx.abs() {
        if dy >= 0 {
            (Side::Bottom, Side::Top)
        } else {
            (Side::Top, Side::Bottom)
        }
    } else if dx >= 0 {
        (Side::Right, Side::Left)
    } else {
        (Side::Left, Side::Right)
    }
}

/// Gives every edge its own port on each side it uses. Ports spread along
/// the border interior, ordered by the position of the far endpoint so
/// edges from one box fan out without crossing at the port. When one side
/// carries more edges than it has cells, the extra ports step outward in
/// bands.
fn assign_ports(
    nodes: &[NodeBox],
    edges: &[EdgeSpec],
    axis: FlowAxis,
) -> Vec<((i32, i32), (i32, i32))> {
    let mut groups: HashMap<(usize, Side), Vec<usize>> = HashMap::new();
    let mut sides: Vec<(Side, Side)> = Vec::with_capacity(edges.len());
    for (index, edge) in edges.iter().enumerate() {
        let (src, tgt) = sides_for(&nodes[edge.from], &nodes[edge.to], axis);
        sides.push((src, tgt));
        if edge.from != edge.to {
            groups.entry((edge.from, src)).or_default().push(index);
            groups.entry((edge.to, tgt)).or_default().push(index);
        }
    }

    let mut ports: Vec<((i32, i32), (i32, i32))> = vec![((0, 0), (0, 0)); edges.len()];
    for ((node_index, side), mut group) in groups {
        let node = &nodes[node_index];
        group.sort_by_key(|&index| {
            let edge = &edges[index];
            let other = if edge.from == node_index {
                &nodes[edge.to]
            } else {
                &nodes[edge.from]
            };
            let (cx, cy) = other.center();
            if side.horizontal() { cx } else { cy }
        });
        for (slot, &index) in group.iter().enumerate() {
            let cell = port_cell(node, side, slot as i32);
            if edges[index].from == node_index {
                ports[index].0 = cell;
            } else {
                ports[index].1 = cell;
            }
        }
    }
    ports
}

/// Slot `slot` on `side`, stepping outward in bands once the border is
/// full. Slots skip the corner cells.
fn port_cell(node: &NodeBox, side: Side, slot: i32) -> (i32, i32) {
    if side.horizontal() {
        let capacity = (node.w - 2).max(1);
        let band = slot / capacity;
        let along = 1 + slot % capacity;
        let y = match side {
            Side::Top => node.y - 1 - band,
            _ => node.y + node.h + band,
        };
        (node.x + along, y)
    } else {
        let capacity = (node.h - 2).max(1);
        let band = slot / capacity;
        let along = 1 + slot % capacity;
        let x = match side {
            Side::Left => node.x - 1 - band,
            _ => node.x + node.w + band,
        };
        (x, node.y + along)
    }
}

/// A small right-hand loop for an edge that points at its own node.
fn self_loop(node: &NodeBox, src: (i32, i32), tgt: (i32, i32)) -> Vec<(i32, i32)> {
    let right = node.x + node.w + 3;
    let bottom = node.y + node.h + 2;
    vec![
        src,
        (right, src.1),
        (right, bottom),
        (tgt.0, bottom),
        tgt,
    ]
}

/// Straight two-turn fallback when A* finds nothing.
fn direct(src: (i32, i32), tgt: (i32, i32)) -> Vec<(i32, i32)> {
    if src.0 == tgt.0 || src.1 == tgt.1 {
        vec![src, tgt]
    } else {
        vec![src, (tgt.0, src.1), tgt]
    }
}

/// The cells a polyline covers, corners included.
/// Every cell a polyline covers, tagged with its travel axis: 1 for a
/// horizontal run, 2 for a vertical one.
fn expand_axes(points: &[(i32, i32)]) -> Vec<((i32, i32), u8)> {
    let mut cells = Vec::new();
    for w in points.windows(2) {
        let (from, to) = (w[0], w[1]);
        if from.1 == to.1 {
            for x in from.0.min(to.0)..=from.0.max(to.0) {
                cells.push(((x, from.1), 1));
            }
        } else {
            for y in from.1.min(to.1)..=from.1.max(to.1) {
                cells.push(((from.0, y), 2));
            }
        }
    }
    cells
}

fn longest_shared_run(cells: &[Vec<((i32, i32), u8)>], nodes: &[NodeBox]) -> usize {
    let mut owner: HashMap<(i32, i32), (usize, u8)> = HashMap::new();
    let mut shared: HashMap<(i32, i32), u8> = HashMap::new();
    for (index, list) in cells.iter().enumerate() {
        for &(cell, axis) in list {
            match owner.get(&cell) {
                // Two edges on the same axis at one cell are running
                // together — that is the corridor this metric hunts.
                // Perpendicular edges merely cross, which is fine.
                Some(&(first, first_axis)) if first != index && first_axis == axis => {
                    shared.insert(cell, axis);
                }
                Some(_) => {}
                None => {
                    owner.insert(cell, (index, axis));
                }
            }
        }
    }
    let mut longest = 0;
    for (&cell, &axis) in &shared {
        // A cell beside a node is a port touch, not a corridor.
        if nodes.iter().any(|node| beside_border(node, cell)) {
            continue;
        }
        let mut run = 1;
        let (dx, dy) = if axis == 1 { (1, 0) } else { (0, 1) };
        for sign in [-1, 1] {
            let (mut x, mut y) = (cell.0 + dx * sign, cell.1 + dy * sign);
            while shared.get(&(x, y)) == Some(&axis) {
                run += 1;
                x += dx * sign;
                y += dy * sign;
            }
        }
        longest = longest.max(run);
    }
    longest
}

/// True when `cell` sits in the one-cell band just outside `node`.
fn beside_border(node: &NodeBox, cell: (i32, i32)) -> bool {
    if node.contains(cell.0, cell.1) {
        return false;
    }
    let (x0, x1) = (node.x - 1, node.x + node.w);
    let (y0, y1) = (node.y - 1, node.y + node.h);
    cell.0 >= x0 && cell.0 <= x1 && cell.1 >= y0 && cell.1 <= y1
}

/// Chooses a free row or column for a label, preferring the longest
/// segment. Returns the label's centre cell, or `None` when every
/// candidate would cover a node, another label, or another edge.
/// One straight run of a route, as start, end, and length in cells.
type Segment = ((i32, i32), (i32, i32), i32);

fn place_label(
    nodes: &[NodeBox],
    cells: &[Vec<(i32, i32)>],
    labels: &[(i32, i32, usize)],
    edge: usize,
    points: &[(i32, i32)],
    len: i32,
    extent: (i32, i32),
) -> Option<(i32, i32)> {
    let mut segments: Vec<Segment> = points
        .windows(2)
        .map(|w| {
            let len = (w[1].0 - w[0].0).abs() + (w[1].1 - w[0].1).abs();
            (w[0], w[1], len)
        })
        .collect();
    segments.sort_by_key(|&(_, _, len)| -len);

    let blocked: HashMap<(i32, i32), ()> = cells
        .iter()
        .enumerate()
        .filter(|(index, _)| *index != edge)
        .flat_map(|(_, list)| list.iter().copied())
        .map(|cell| (cell, ()))
        .collect();

    for (from, to, seg_len) in segments {
        if seg_len < 1 {
            continue;
        }
        let mid = ((from.0 + to.0) / 2, (from.1 + to.1) / 2);
        // Beside the line first; then on the line itself, which masks
        // the stroke with the text — the placement readers prefer when
        // there is no spare row. Crossing a *different* edge is still
        // refused, so a mask never hides someone else's route.
        let candidates: [(i32, i32); 3] = if from.1 == to.1 {
            [(mid.0, mid.1 - 1), (mid.0, mid.1 + 1), mid]
        } else {
            [
                (mid.0 + len / 2 + 2, mid.1),
                (mid.0 - len / 2 - 2, mid.1),
                mid,
            ]
        };
        for (cx, cy) in candidates {
            let lo = cx - len / 2;
            // A label must stay on the canvas: a clipped word reads as a
            // different word.
            if lo < 1 || lo + len > extent.0 - 1 || cy < 1 || cy > extent.1 - 1 {
                continue;
            }
            let span: Vec<(i32, i32)> = (lo..lo + len).map(|x| (x, cy)).collect();
            let clear = span.iter().all(|&cell| {
                !nodes.iter().any(|node| node.contains(cell.0, cell.1))
                    && !blocked.contains_key(&cell)
