fn draw_dots(
    points: &[(i32, i32)],
    speed: f64,
    phase: usize,
    style: Style,
    arrow: Option<(i32, i32)>,
    buf: &mut Buffer,
) {
    let area = buf.area;
    let offset = phase as f64 * speed;
    let total: i32 = points
