rows = []
for path in files:
    cost = 0.0
    n = 0
    models = collections.Counter()
    first_user = None
    for line in open(path, encoding="utf-8", errors="replace"):
        line = line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except Exception:
            continue
        if rec.get("type") == "message":
            msg = rec.get("message") or {}
            role = msg.get("role")
