                n += 1
                usage = msg.get("usage") or {}
                cost += float((usage.get("cost") or {}).get("total") or 0.0)
                models[msg.get("model") or "?"] += 1
            elif role == "user" and first_user is None:
                content = msg.get("content")
                if isinstance(content, list):
                    txt = " ".join(p.get("text", "") for p in content if isinstance(p, dict))
                else:
                    txt = str(content or "")
                txt = txt.strip()
                if txt and not txt.startswith(("Sub-agent ", "The conversation history ", "<")):
                    first_user = txt[:110].replace("\n", " ")
    rows.append((cost, n, os.path.basename(path), dict(models), first_user))

rows.sort(reverse=True)
total = sum(r[0] for r in rows)
print("TOTAL cost:", round(total, 6))
for cost, n, name, models, first in rows:
    print(f"{cost:9.4f} {n:4d} {name[:46]} {models}")
    if first:
        print("        task:", first)

