# find the largest inter-record gaps regardless of role
import json
from pathlib import Path
from datetime import datetime, timezone

base = Path("/Users/aviral/.pi/agent/sessions/--Users-aviral-.herdr-worktrees-dotfiles-fix-visualize-skill--")
SESSIONS = {
    "r04": base / "2026-11-02T12-00-40-521Z_61a5e131-8b5bd973-86dc1336-d907.jsonl",
    "r05": base / "2026-11-02T14-02-56-216Z_5d993c88-1e9ea37d-8823b476-309c.jsonl",
}

def ts(v):
    if isinstance(v, (int, float)):
        if v > 1e12: v = v / 1000.0
        return datetime.fromtimestamp(v, tz=timezone.utc)
    return datetime.fromisoformat(str(v).replace("Z", "+00:00"))

def describe(m):
    role = m.get("role")
    parts = []
    for c in m.get("content", []):
        if not isinstance(c, dict): continue
        if c.get("type") == "toolCall":
            args = c.get("arguments") or {}
            cmd = str(args.get("command", ""))[:60].replace("\n", " ")
            parts.append(f"call:{c.get('name')}({cmd})" if cmd else f"call:{c.get('name')}")
        elif c.get("type") == "thinking":
            parts.append(f"think[{len(c.get('thinking',''))}ch]")
        elif c.get("type") == "text":
            parts.append(f"text[{len(c.get('text',''))}ch]")
    return role, " ".join(parts)[:110]

for name, path in SESSIONS.items():
    raw = [json.loads(l) for l in path.read_text().splitlines() if l.strip()]
    msgs = [(r.get("timestamp"), r["message"]) for r in raw
            if r.get("type") == "message" and isinstance(r.get("message"), dict)]
    msgs.sort(key=lambda x: ts(x[0]))
    gaps = []
    for (t0, m0), (t1, m1) in zip(msgs, msgs[1:]):
        gaps.append(((ts(t1) - ts(t0)).total_seconds(), ts(t0).strftime("%H:%M:%S"), describe(m0), describe(m1)))
    gaps.sort(reverse=True)
    print(f"===== {name}: top 8 inter-record gaps =====")
    for g in gaps[:8]:
        print(f"  {round(g[0]):>4}s after {g[1]} | {g[2][:70]}")
        print(f"       {'':>13}| next: {g[3][:80]}")
    print()

