# compute structural metrics for all eight cases from their expected relations
import json
from pathlib import Path
from collections import Counter

base = Path("/Users/aviral/.herdr/worktrees/dotfiles/fix-visualize-skill/docs/visualize-eval/cases")
cases = ["pipeline","network","homelab-nic-trace","server-nic-layout",
        "datacenter-redundancy","modal-machine-manager","modal-runtime","gb300-rack-software"]

def weak_components(nodes, edges):
    parent = {n: n for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb: parent[ra] = rb
    return len(Counter(find(n) for n in nodes))

def longest_chain(nodes, edges):
    # BFS-based approximate depth in the directed graph
    indeg = Counter(b for _, b in edges)
    adj = {}
    for a, b in edges: adj.setdefault(a, []).append(b)
    depth = {n: 0 for n in nodes if indeg[n] == 0}
    frontier = list(depth)
    d = 0
    while frontier:
        nxt = []
        for u in frontier:
            for v in adj.get(u, []):
                if v not in depth:
                    depth[v] = d + 1; nxt.append(v)
        frontier = nxt; d += 1
    return max(depth.values()) + 1 if depth else 0

rows = []
for c in cases:
    d = json.loads((base / c / "expected.json").read_text())
    hr = d.get("historical_reference", {})
    nodes = [n["id"] if isinstance(n, dict) else n for n in hr.get("nodes", [])]
    raw_edges = hr.get("edges", [])
    edges, labels, quals = [], [], 0
    for e in raw_edges:
        if isinstance(e, dict):
            a, b = e.get("from"), e.get("to")
            lab = e.get("label") or ""
        else:
            a, b = e[0], e[1]; lab = ""
        edges.append((a, b))
        if lab:
            labels.append(lab)
            if any(q in lab.lower() for q in ("?", "claimed", "historical", "standby", "uncertain")):
                quals += 1
    eset = set(edges)
    antipar = sum(1 for (a, b) in eset if (b, a) in eset) // 2
    outd = Counter(a for a, _ in edges)
    ind = Counter(b for _, b in edges)
    anim = d.get("animation") or {}
    rows.append({
        "case": c, "N": len(nodes), "E": len(edges),
        "maxfan": max(list(outd.values()) + list(ind.values()) or [0]),
        "antipar": antipar,
        "planes": weak_components(nodes, edges),
        "chain": longest_chain(nodes, edges),
        "labels": len(labels), "qual_labels": quals,
        "dots": (anim.get("required") if isinstance(anim, dict) else None) or anim or "?",
