    pub y: i32,
    pub w: i32,
    pub h: i32,
}

impl Region {
    /// A region box around the given member bounds (inclusive cells).
    pub fn around(name: impl Into<String>, left: i32, top: i32, right: i32, bottom: i32) -> Self {
        // One border cell on each side, kept inside the canvas.
        let x = (left - 1).max(0);
        let y = (top - 1).max(0);
        Self {
            name: name.into(),
            x,
            y,
            w: right + 2 - x,
            h: bottom + 2 - y,
        }
    }
}

