            .map(|&(x, y)| (x as f64, y as f64))
            .collect(),
    )
    .with_dot_cells(
        planned
            .dot_cells
            .iter()
            .map(|&(x, y)| (x as f64, y as f64))
            .collect(),
    )
    .with_detached_src(planned.detached_src)
}

