/// Paints a dotted rectangle: the boundary of a zoomed-in component's
/// contents. Dots never look like a node border, so the reader reads it as
/// "inside this box" rather than as another element.
fn draw_dotted_frame(
    frame: &mut Frame,
    flow: &Graph,
    canvas: Rect,
    x: i32,
    y: i32,
    w: i32,
    h: i32,
    color: Color,
) {
    let style = Style::default().bg(flow.theme.palette().canvas_bg).fg(color);
    let mut line = String::new();
    for _ in 0..w.max(1) {
        line.push('\u{00b7}');
    }
    for row in [y, y + h - 1] {
        put_world_text(frame, flow, canvas, x, row, &line, style);
    }
    for row in (y + 1)..(y + h - 1) {
        put_world_text(frame, flow, canvas, x, row, "\u{00b7}", style);
        put_world_text(frame, flow, canvas, x + w - 1, row, "\u{00b7}", style);
    }
}

/// Repaints a focus node's border with double-line glyphs: the box a reader
/// can zoom into wears a second ring.
fn draw_double_borders(
    frame: &mut Frame,
    flow: &Graph,
    canvas: Rect,
    sections: &[SectionReport],
    color: Color,
) {
    let focus: Vec<&str> = sections
        .iter()
        .flat_map(|section| section.focus.iter().map(String::as_str))
        .collect();
    if focus.is_empty() {
        return;
    }
    let style = Style::default().bg(flow.theme.palette().canvas_bg).fg(color);
    for node in flow.nodes() {
        if !focus.contains(&node.id.as_str()) {
            continue;
        }
        let (x, y) = (node.position.x, node.position.y);
        let (w, h) = (node.width, node.height);
        let corners = [
            ('\u{2554}', x, y),
            ('\u{2557}', x + w - 1.0, y),
            ('\u{255a}', x, y + h - 1.0),
            ('\u{255d}', x + w - 1.0, y + h - 1.0),
        ];
        for (glyph, cx, cy) in corners {
            let text = glyph.to_string();
            put_world_text(frame, flow, canvas, cx as i32, cy as i32, &text, style);
