#[test]
fn enclosure_frames_wrap_their_members() {
    // The dotted boundary must enclose the nested cells it names: every member
    // node's drawn rectangle sits strictly inside a frame, with one cell of
    // clearance. rataflow's Node::position is the CENTRE, so a corner/centre
    // mix-up shows up here as a frame shifted by half a box.
    let spec_json = r#"{
      "theme": "gruvbox", "direction": "lr",
      "diagrams": [
        {"id": "l1", "title": "L1", "description": "context", "direction": "lr",
         "nodes": [{"id": "a", "label": "Alpha"}, {"id": "b", "label": "Beta"}],
         "edges": [{"from": "a", "to": "b", "label": "ab"}]},
        {"id": "l2", "title": "L2", "description": "containers", "direction": "lr",
         "enclosures": [["x", "y"], ["z"]],
         "nodes": [{"id": "x", "label": "Ex"}, {"id": "y", "label": "Why"}, {"id": "z", "label": "Zed"}],
         "edges": [{"from": "x", "to": "y", "label": "xy"}, {"from": "y", "to": "z", "label": "yz"}]}
      ]
    }"#;
    let spec = rataflow_view::Spec::from_json_str(spec_json).expect("spec parses");
    let (graph, report) = rataflow_view::build(&spec).expect("graph builds");
    assert_eq!(report.sections.len(), 2);
    let section = &report.sections[1];
    assert_eq!(section.frames.len(), 2, "one frame per enclosure group");

    for node in graph.nodes() {
        let Some((_, local)) = node.id.split_once(':') else { continue };
        if !matches!(local, "x" | "y" | "z") {
            continue;
        }
        // flow node positions are centres in canvas space
        let (nx, ny) = (node.position.x, node.position.y);
        let (x0, y0) = ((nx - node.width / 2.0).round() as i32, (ny - node.height / 2.0).round() as i32);
        let (x1, y1) = (x0 + node.width as i32 - 1, y0 + node.height as i32 - 1);
        let inside = section.frames.iter().any(|&(fx, fy, fw, fh)| {
            x0 > fx && y0 > fy && x1 < fx + fw - 1 && y1 < fy + fh - 1
        });
        assert!(
            inside,
            "node {local} at ({x0},{y0})..({x1},{y1}) is not strictly inside any frame {:?}",
            section.frames
        );
    }
}
