from pathlib import Path

p = Path("rataflow/src/lib.rs")
t = p.read_text()

# 1) SectionReport keeps the MEMBER LISTS, not pre-layout coordinates: the
#    library re-runs its own layout, so a rect captured at build time drifts.
t = t.replace(
    """    /// World rects `(x, y, w, h)` of this diagram's dotted enclosures: one
    /// box per contiguous group of nested cells.
    pub frames: Vec<(i32, i32, i32, i32)>,""",
    """    /// One entry per dotted enclosure: the node ids it wraps. The rect is
    /// computed from the LIVE node positions at draw time, because the
    /// library runs its own layout after the graph is built and a rect
    /// captured earlier drifts away from the boxes it should surround.
    pub enclosures: Vec<Vec<String>>,""",
    1,
)

# 2) build_canvas: store the groups; keep computing nothing positional
t = t.replace(
    """        let frames: Vec<(i32, i32, i32, i32)> = if group_rects.is_empty() {
            diagram
                .enclosed
                .then(|| vec![(0, top - pad, base_width + pad * 2, base_height + pad * 2)])
                .unwrap_or_default()
        } else {
            group_rects
                .iter()
                .map(|&(x0, y0, x1, y1)| {
                    // Two cells of clearance: the boundary must read as a
                    // frame AROUND the contents, never flush with a border.
                    (
                        x0 + dx as i32 - 2,
                        y0 + dy as i32 - 2,
                        x1 - x0 + 5,
                        y1 - y0 + 5,
                    )
                })
                .collect()
        };""",
    """        // The whole-band form has no member list; it names every node of the
        // section, so the rect is derived exactly like a member group.
        let enclosures: Vec<Vec<String>> = if group_rects.is_empty() {
            if diagram.enclosed {
                vec![graph.nodes.iter().map(|n| n.id.clone()).collect()]
            } else {
                Vec::new()
            }
        } else {
            groups.clone()
        };
        let frames: Vec<(i32, i32, i32, i32)> = Vec::new();""",
    1,
)

t = t.replace(
    """            rule_width: 0,
            frames: frames.clone(),
            focus,""",
    """            rule_width: 0,
            enclosures,
            focus,""",
    1,
)

# 3) crossing accounting uses live rects
t = t.replace(
    """        for &(fx, fy, fw, fh) in frames.iter() {""",
    """        for (fx, fy, fw, fh) in enclosure_rects(&flow, &enclosures) {""",
    1,
)

# 4) helper: member groups -> rects, from live positions
t = t.replace(
    """/// A node's drawn rectangle `(x, y, w, h)` in its own cell space.""",
    """/// The dotted-box rects for a section's enclosure groups, from the LIVE node
/// positions. Two cells of clearance keep the boundary a frame AROUND the
/// contents instead of a line flush against a border.
pub fn enclosure_rects(flow: &Graph, groups: &[Vec<String>]) -> Vec<(i32, i32, i32, i32)> {
    groups
        .iter()
        .filter_map(|members| {
            let ids: Vec<&str> = members.iter().map(String::as_str).collect();
            let mut rect: Option<(i32, i32, i32, i32)> = None;
            for node in flow.nodes() {
                if !ids.contains(&node.id.as_str()) {
                    continue;
                }
                let (x, y, w, h) = node_rect(node);
                let (x1, y1) = (x + w - 1, y + h - 1);
                rect = Some(match rect {
                    None => (x, y, x1, y1),
                    Some((ax, ay, bx, by)) => (ax.min(x), ay.min(y), bx.max(x1), by.max(y1)),
                });
            }
            rect.map(|(x0, y0, x1, y1)| (x0 - 2, y0 - 2, x1 - x0 + 5, y1 - y0 + 5))
        })
        .collect()
}

/// A node's drawn rectangle `(x, y, w, h)` in its own cell space.""",
    1,
)

# 5) drawing uses live rects
t = t.replace(
    """        for &(fx, fy, fw, fh) in &section.frames {
            draw_dotted_frame(frame, flow, canvas, fx, fy, fw, fh, palette.subtle);
        }""",
    """        for (fx, fy, fw, fh) in enclosure_rects(flow, &section.enclosures) {
            draw_dotted_frame(frame, flow, canvas, fx, fy, fw, fh, palette.subtle);
        }""",
    1,
)
p.write_text(t)
print("frames now computed at draw time")

