#[test]
fn enclosure_frames_render_around_their_members() {
    let text = std::fs::read_to_string("../docs/visualize-eval/rounds/14/c4-retry/specs/c4-canvas.json")
        .expect("spec file");
    let (mut graph, report) = build(&text);
    let mut terminal = ratatui::Terminal::new(ratatui::backend::TestBackend::new(260, 90)).expect("terminal");
    terminal
        .draw(|frame| rataflow_view::draw_canvas(frame, &mut graph, "test", &report.sections))
        .expect("draw");
    let buffer = terminal.backend().buffer().clone();
    let width = buffer.area.width as usize;
    let cells: Vec<&str> = buffer.content.iter().map(|c| c.symbol()).collect();
    let at = |x: usize, y: usize| cells[y * width + x];

    for section in &report.sections {
        for &(fx, fy, fw, fh) in &section.enclosures {
            // Header occupies row 0, so world y maps to screen y + 1.
            let top = (fy + 1) as usize;
            let bottom = (fy + 1 + fh - 1) as usize;
            let left = fx as usize;
            let right = (fx + fw - 1) as usize;
            let mut dots = 0;
            for x in left..=right {
                if at(x, top) == "\u{00b7}" { dots += 1; }
                if at(x, bottom) == "\u{00b7}" { dots += 1; }
            }
            for y in (top + 1)..bottom {
                if at(left, y) == "\u{00b7}" { dots += 1; }
                if at(right, y) == "\u{00b7}" { dots += 1; }
            }
            let perimeter = 2 * (fw as usize + fh as usize) - 4;
            assert!(
                dots * 2 >= perimeter,
                "frame {section_diagram} at ({fx},{fy}) {fw}x{fh}: only {dots}/{perimeter} perimeter cells are dots",
                section_diagram = section.diagram
            );
        }
    }
}

