            None => box_rect,
            Some((x0, y0, x1, y1)) => (
                x0.min(box_rect.0),
                y0.min(box_rect.1),
                x1.max(box_rect.2),
                y1.max(box_rect.3),
            ),
        });
    }
    let Some((x0, y0, x1, y1)) = bounds else {
        return;
    };
    let (bx0, by0, bx1, by1) = (x0 - 1, y0 - 1, x1 + 1, y1 + 1);
    if bx1 - bx0 < 4 || by1 - by0 < 3 {
        return;
    }
    if bx0 < canvas.x as i32 || by0 < canvas.y as i32 {
        return;
    }
    if bx1 >= (canvas.x + canvas.width) as i32 || by1 >= (canvas.y + canvas.height) as i32 {
        return;
    }
    let put = |frame: &mut Frame, x: i32, y: i32, ch: char, force: bool| {
        let cell = &mut frame.buffer_mut()[(x as u16, y as u16)];
        if force || cell.symbol() == " " {
            cell.set_char(ch).set_style(style);
        }
    };
    for x in bx0..=bx1 {
        let left = if x == bx0 { '\\u{2554}' } else { '\\u{2550}' };
        let right = if x == bx1 { '\\u{2557}' } else { '\\u{2550}' };
        put(frame, x, by0, left, false);
        let bl = if x == bx0 { '\\u{255a}' } else { '\\u{2550}' };
        let br = if x == bx1 { '\\u{255d}' } else { '\\u{2550}' };
        put(frame, x, by1, bl, false);
        let _ = (right, br);
    }
    for y in (by0 + 1)..by1 {
        put(frame, bx0, y, '\\u{2551}', false);
        put(frame, bx1, y, '\\u{2551}', false);
    }
    // The label rides the top edge, two cells in, and wins over the rule.
    if (label.chars().count() as i32) + 4 < (bx1 - bx0) {
        for (offset, ch) in label.chars().enumerate() {
            put(frame, bx0 + 2 + offset as i32, by0, ch, true);
        }
    }
}

/// Finds a node's drawn box on screen by its label text.
///
/// The label is unique enough inside one canvas; when it repeats (the same
/// service in two diagrams) the first match inside this section's rows wins,
/// so two diagrams never steal each other's boxes.
fn find_node_box(frame: &Frame, canvas: Rect, id: &str, label: &str) -> Option<(i32, i32, i32, i32)> {
    let _ = id;
    let buffer = frame.buffer_mut();
    let (cx0, cy0) = (canvas.x as i32, canvas.y as i32);
    let (cx1, cy1) = (
        (canvas.x + canvas.width) as i32 - 1,
        (canvas.y + canvas.height) as i32 - 1,
    );
    let width = buffer.area.width as i32;
    let symbol = |x: i32, y: i32| -> Option<char> {
        if x < cx0 || y < cy0 || x > cx1 || y > cy1 {
            return None;
        }
        let idx = (y as u16 as usize) * width as usize + x as usize;
        buffer.content.get(idx).map(|c| c.symbol().chars().next().unwrap_or(' '))
    };
    let needle: Vec<char> = label.chars().collect();
    if needle.is_empty() {
        return None;
    }
    for y in cy0..=cy1 {
        let mut run: Vec<char> = Vec::new();
        for x in cx0..=cx1 {
            run.push(symbol(x, y).unwrap_or(' '));
            if run.len() > needle.len() {
                run.remove(0);
            }
            if run == needle {
                let start_x = x - needle.len() as i32 + 1;
                // Walk up to the border row containing this label.
                let mut top = y;
                while top > cy0 {
                    let above = symbol(start_x.saturating_sub(1), top - 1);
                    let corner = symbol(start_x.saturating_sub(1), top);
                    if matches!(above, Some('\\u{256d}' | '\\u{250c}' | '\\u{2554}'))
                        || matches!(corner, Some('\\u{2502}' | '\\u{2551}' | '\\u{2503}'))
                    {
                        break;
                    }
                    top -= 1;
                }
                let top = top.max(cy0);
                // Left and right edges on the label row.
                let mut left = start_x;
                while left > cx0 && !matches!(symbol(left - 1, top), Some('\\u{2502}' | '\\u{2551}' | '\\u{2503}')) {
                    left -= 1;
                }
                let mut right = start_x;
                while right < cx1 && !matches!(symbol(right + 1, top), Some('\\u{2502}' | '\\u{2551}' | '\\u{2503}')) {
                    right += 1;
                }
                // Bottom edge.
                let mut bottom = y;
                while bottom < cy1 && !matches!(symbol(left, bottom + 1), Some('\\u{2570}' | '\\u{2514}' | '\\u{255a}')) {
                    bottom += 1;
                }
                return Some((left - 1, top - 1, right + 1, bottom + 1));
            }
        }
    }
    None
}

