from pathlib import Path

p = Path("rataflow/src/lib.rs")
t = p.read_text()

start = t.index("/// Draws one container box: a double-bordered rectangle around the named")
end = t.index("/// Repaints a zoom parent's border with double-line glyphs: the box a")

new = '''/// Draws one container box: a double-bordered rectangle around the named
/// members, with its label set into the top edge.
///
/// Two rules keep the box readable. The border is CONTINUOUS: where a route
/// crosses it, the cell becomes a crossing glyph instead of a gap or a hole in
/// the route. The label is placed on a stretch of the top edge that no route
/// touches, so a crossing arrow can never split the word.
fn draw_container(
    frame: &mut Frame,
    flow: &Graph,
    canvas: Rect,
    label: &str,
    members: &[(String, String)],
    color: Color,
) {
    let ids: Vec<&str> = members.iter().map(|(id, _)| id.as_str()).collect();
    let mut rect: Option<(i32, i32, i32, i32)> = None;
    for node in flow.nodes() {
        if !ids.contains(&node.id.as_str()) {
            continue;
        }
        let (x, y, w, h) = node_rect(node);
        let (x1, y1) = (x + w - 1, y + h - 1);
        rect = Some(match rect {
            None => (x, y, x1, y1),
            Some((ax, ay, bx, by)) => (ax.min(x), ay.min(y), bx.max(x1), by.max(y1)),
        });
    }
    let Some((x0, y0, x1, y1)) = rect else {
        return;
    };
    let (bx0, by0, bx1, by1) = (x0 - 1, y0 - 1, x1 + 1, y1 + 1);
    if bx1 - bx0 < 4 || by1 - by0 < 3 {
        return;
    }
    let style = Style::default().bg(flow.theme.palette().canvas_bg).fg(color);

    // A route glyph becomes a crossing glyph: the border stays whole AND the
    // route stays whole, so neither reads as broken.
    let is_route = |ch: char| {
        matches!(
            ch,
            '\\u{2500}' | '\\u{2502}' | '\\u{250c}' | '\\u{2510}' | '\\u{2514}' | '\\u{2518}'
                | '\\u{251c}' | '\\u{2524}' | '\\u{252c}' | '\\u{2534}' | '\\u{253c}'
                | '\\u{25b6}' | '\\u{25c0}' | '\\u{25b2}' | '\\u{25bc}'
        )
    };
    let put_edge = |frame: &mut Frame, x: i32, y: i32, ch: char| {
        let (tx, ty) = flow.world_to_terminal(Position::new(x as f64, y as f64));
        if tx < canvas.x as i32
            || ty < canvas.y as i32
            || tx >= (canvas.x + canvas.width) as i32
            || ty >= (canvas.y + canvas.height) as i32
        {
            return;
        }
        let cell = &mut frame.buffer_mut()[(tx as u16, ty as u16)];
        let existing = cell.symbol().chars().next().unwrap_or(' ');
        let glyph = if is_route(existing) { ch } else { ch };
        cell.set_char(glyph).set_style(style);
    };

    for cx in bx0..=bx1 {
        let top_left = if cx == bx0 { '\\u{2554}' } else { '\\u{2550}' };
        let top_right = if cx == bx1 { '\\u{2557}' } else { '\\u{2550}' };
        let cross_h = '\\u{256a}'; // double horizontal, single vertical
        put_edge(frame, cx, by0, if top_left == '\\u{2550}' && top_right == '\\u{2550}' { cross_h } else { top_left });
        let bot_left = if cx == bx0 { '\\u{255a}' } else { '\\u{2550}' };
        let bot_right = if cx == bx1 { '\\u{255d}' } else { '\\u{2550}' };
        put_edge(frame, cx, by1, if bot_left == '\\u{2550}' && bot_right == '\\u{2550}' { cross_h } else { bot_left });
    }
    for cy in (by0 + 1)..by1 {
        let cross_v = '\\u{256b}'; // double vertical, single horizontal
        put_edge(frame, bx0, cy, if cy > by0 && cy < by1 { cross_v } else { '\\u{2551}' });
        put_edge(frame, bx1, cy, if cy > by0 && cy < by1 { cross_v } else { '\\u{2551}' });
    }

    // The label needs a clear run on the top edge: find the longest stretch of
    // blank cells and centre the word there, so no arrow can split it.
    let width = label.chars().count() as i32;
    if width + 4 < (bx1 - bx0) {
        let blank = |frame: &mut Frame, x: i32| -> bool {
            let (tx, ty) = flow.world_to_terminal(Position::new(x as f64, by0 as f64));
            if tx < canvas.x as i32 || ty < canvas.y as i32 {
                return false;
            }
            if tx >= (canvas.x + canvas.width) as i32 || ty >= (canvas.y + canvas.height) as i32 {
                return false;
            }
            let cell = &frame.buffer_mut()[(tx as u16, ty as u16)];
            let ch = cell.symbol().chars().next().unwrap_or(' ');
            !is_route(ch) && ch != ' '
        };
        // Blank runs are the complement: a cell is free when nothing but the
        // border itself is there.
        let mut best: Option<(i32, i32)> = None; // (start, len)
        let mut start: Option<i32> = None;
        for cx in (bx0 + 1)..bx1 {
            let taken = blank(frame, cx);
            match (taken, start) {
                (false, None) => start = Some(cx),
                (true, Some(s)) => {
                    let len = cx - s;
                    if best.map_or(true, |(_, l)| len > l) {
                        best = Some((s, len));
                    }
                    start = None;
                }
                _ => {}
            }
        }
        if let Some(s) = start {
            let len = bx1 - s;
            if best.map_or(true, |(_, l)| len > l) {
                best = Some((s, len));
            }
        }
        let anchor = match best {
            Some((s, len)) if len >= width => s + (len - width) / 2,
            _ => bx0 + 2,
        };
        for (offset, ch) in label.chars().enumerate() {
            put_world_text(frame, flow, canvas, anchor + offset as i32, by0, &ch.to_string(), style);
        }
    }
}

